SELECT 'SensorLog cols' AS check_name, COUNT(*) AS found, 5 AS expected FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='sensor_dashboard' AND TABLE_NAME='SensorLog' AND COLUMN_NAME IN ('timeConfidence','readLatencyMs','tickJitterMs','queueDelayMs','recordedAt') UNION ALL SELECT 'DeviceStatus cols', COUNT(*), 4 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='sensor_dashboard' AND TABLE_NAME='DeviceStatus' AND COLUMN_NAME IN ('lastSeen','bootID','bootAt','isOnline') UNION ALL SELECT 'new tables', COUNT(*), 2 FROM information_schema.TABLES WHERE TABLE_SCHEMA='sensor_dashboard' AND TABLE_NAME IN ('DeviceEvent','SamplingConfig') UNION ALL SELECT 'seed period row', COUNT(*), 1 FROM sensor_dashboard.SamplingConfig;
